import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { formatRate } from '@stateproof/core';
import { formatUsd } from '@stateproof/submission';
import type { BenchmarkView } from '../shared/types';

/**
 * The benchmark page's data, read from the committed final evaluation.
 *
 * Nothing here recomputes or restates a metric: `submission/final-evaluation.json`
 * is generated by the frozen comparison generator, and this reads it. If that
 * file is missing the product says so rather than showing a plausible table.
 */

interface FinalMetricView {
  safetyViolationRecall: number | null;
  safetyViolationCounts: [number, number];
  falseViolationRate: number | null;
  falseViolationCounts: [number, number];
  completeDiagnosisRate: number | null;
  completeDiagnosisCounts: [number, number];
  balancedVerdictAccuracy: number | null;
  evidenceRefValidity: number | null;
  evidenceRefCounts: [number, number];
  caseCount: number;
}

interface FinalUsageView {
  modelCalls: number;
  totalTokens: number;
  inputTokens: number;
  outputTokens: number;
  modelCallWallMs: number | null;
  deterministicVerificationMs: number | null;
  endToEndElapsedMs: number;
}

interface FinalEvaluation {
  lockedEvaluationComplete: boolean;
  qualityGuardrailsMet: boolean;
  observedDevelopment: { baseline: FinalMetricView; stateproof: FinalMetricView };
  observedLocked: { baseline: FinalMetricView | null; stateproof: FinalMetricView | null };
  recomputedCombined: { baseline: FinalMetricView | null; stateproof: FinalMetricView | null };
  usage: {
    baselineCombined: FinalUsageView | null;
    stateproofFirstDeployment: FinalUsageView;
    stateproofRepeatedVerification: FinalUsageView;
  };
  efficiency: {
    firstDeploymentCallReduction: number | null;
    firstDeploymentTokenReduction: number | null;
    repeatedCallReduction: number | null;
    repeatedTokenReduction: number | null;
    breakEvenSuiteRuns: number | null;
    cost: {
      baselineUsd: number | null;
      firstDeploymentUsd: number | null;
      repeatedUsd: number | null;
      absoluteSavingsUsd: number | null;
      percentSavings: number | null;
    };
  } | null;
}

export const SCOPE_NOTE =
  'This is a 12-case synthetic evaluation on PhantomBench-Hard-12. It does not establish ' +
  'generalization beyond the submitted benchmark. It shows that StateProof preserved measured ' +
  'quality on the untouched locked split while making repeated verification deterministic and ' +
  'substantially cheaper.';

const CHANGELOG: BenchmarkView['changelog'] = [
  {
    stage: '1',
    title: 'Core-12 baseline saturated',
    outcome: 'A frontier evaluator classified every case correctly; overall accuracy had no headroom.',
  },
  {
    stage: '2',
    title: 'Hard-12 requirement-level baseline saturated',
    outcome: 'Full recall and complete diagnosis again. Cost and determinism became the measurable axis.',
  },
  {
    stage: '3',
    title: 'Ambiguous fixture corrected',
    outcome: 'A false violation traced to the benchmark, not the evaluator. Fixed at the fixture; prompt untouched.',
  },
  {
    stage: '4',
    title: 'Contract Agent v1 — replaced',
    outcome: 'Reusable contracts worked, but the DSL could not express relational scope.',
  },
  {
    stage: '5',
    title: 'Contract Agent v2 — replaced',
    outcome: 'Fixed relational scope; introduced an ambiguous exact-one selector for outbound messages.',
  },
  {
    stage: '6',
    title: 'Contract Agent v3 — final',
    outcome: 'Existential matching plus a lint against under-specified output selectors. All guardrails met.',
  },
  {
    stage: '7',
    title: 'Measured warm verification',
    outcome: 'Three warm runs, byte-identical predictions, zero model calls, no credential present.',
  },
  {
    stage: '8',
    title: 'Untouched locked evaluation',
    outcome: 'Four held-out cases, run exactly once after the source freeze. Both systems perfect.',
  },
];

function metrics(view: FinalMetricView | null): Record<string, string> {
  if (view === null) return {};
  return {
    SVR: `${formatRate(view.safetyViolationRecall)} (${view.safetyViolationCounts[0]}/${view.safetyViolationCounts[1]})`,
    FVR: `${formatRate(view.falseViolationRate)} (${view.falseViolationCounts[0]}/${view.falseViolationCounts[1]})`,
    CDR: `${formatRate(view.completeDiagnosisRate)} (${view.completeDiagnosisCounts[0]}/${view.completeDiagnosisCounts[1]})`,
    BVA: formatRate(view.balancedVerdictAccuracy),
    'Evidence refs': `${formatRate(view.evidenceRefValidity)} (${view.evidenceRefCounts[0]}/${view.evidenceRefCounts[1]})`,
  };
}

function seconds(ms: number | null): string {
  if (ms === null) return 'not isolated';
  return ms < 1000 ? `${ms} ms` : `${(ms / 1000).toFixed(1)} s`;
}

function usageRow(label: string, usage: FinalUsageView | null): BenchmarkView['usage'][number] {
  if (usage === null) {
    return {
      label,
      modelCalls: '—',
      totalTokens: '—',
      modelCallWall: '—',
      deterministicVerification: '—',
      endToEndElapsed: '—',
      apiCost: '—',
    };
  }
  return {
    label,
    modelCalls: usage.modelCalls.toLocaleString('en-US'),
    totalTokens: usage.totalTokens.toLocaleString('en-US'),
    modelCallWall: seconds(usage.modelCallWallMs),
    deterministicVerification: seconds(usage.deterministicVerificationMs),
    endToEndElapsed: seconds(usage.endToEndElapsedMs),
    apiCost: formatUsd(
      usage.inputTokens === 0 && usage.outputTokens === 0
        ? 0
        : (usage.inputTokens * 5) / 1_000_000 + (usage.outputTokens * 25) / 1_000_000,
    ),
  };
}

export function benchmarkView(repoRoot: string): BenchmarkView {
  const filePath = path.join(repoRoot, 'submission', 'final-evaluation.json');
  if (!existsSync(filePath)) {
    throw new Error(
      'submission/final-evaluation.json is missing; run `pnpm submission:finalize` to generate it',
    );
  }
  const final = JSON.parse(readFileSync(filePath, 'utf8')) as FinalEvaluation;

  const reductions: BenchmarkView['reductions'] =
    final.efficiency === null
      ? [
          {
            label: 'Efficiency',
            value: 'Not claimed — a quality guardrail did not hold on the locked or combined result.',
          },
        ]
      : [
          {
            label: 'First deployment, model calls',
            value: formatRate(final.efficiency.firstDeploymentCallReduction) + ' fewer',
          },
          {
            label: 'First deployment, tokens',
            value: formatRate(final.efficiency.firstDeploymentTokenReduction) + ' fewer',
          },
          {
            label: 'First deployment, API cost',
            value: `${formatUsd(final.efficiency.cost.absoluteSavingsUsd)} saved (${formatRate(final.efficiency.cost.percentSavings)})`,
          },
          {
            label: 'Repeated verification',
            value:
              formatRate(final.efficiency.repeatedCallReduction) +
              ' fewer calls and ' +
              formatRate(final.efficiency.repeatedTokenReduction) +
              ' fewer tokens',
          },
          {
            label: 'Break-even',
            value: `${String(final.efficiency.breakEvenSuiteRuns ?? '—')} run(s) of the full suite`,
          },
        ];

  return {
    generatedFrom: 'submission/final-evaluation.json',
    lockedEvaluationComplete: final.lockedEvaluationComplete,
    qualityGuardrailsMet: final.qualityGuardrailsMet,
    scopeNote: SCOPE_NOTE,
    splits: [
      {
        label: 'Development (iterated against)',
        caseCount: final.observedDevelopment.baseline.caseCount,
        baseline: metrics(final.observedDevelopment.baseline),
        stateproof: metrics(final.observedDevelopment.stateproof),
      },
      {
        label: 'Locked (untouched, run once)',
        caseCount: final.observedLocked.baseline?.caseCount ?? 0,
        baseline: metrics(final.observedLocked.baseline),
        stateproof: metrics(final.observedLocked.stateproof),
      },
      {
        label: 'Combined (recomputed from counts)',
        caseCount: final.recomputedCombined.baseline?.caseCount ?? 0,
        baseline: metrics(final.recomputedCombined.baseline),
        stateproof: metrics(final.recomputedCombined.stateproof),
      },
    ],
    usage: [
      usageRow('Frontier baseline, all 12', final.usage.baselineCombined),
      usageRow('StateProof first deployment, all 12', final.usage.stateproofFirstDeployment),
      usageRow('StateProof repeated verification, all 12', final.usage.stateproofRepeatedVerification),
    ],
    changelog: CHANGELOG,
    reductions,
  };
}
